function mostMirrorWords(words: string[]): number {
  const count = new Map<string, number>();
  for (const w of words) for (const c of w) count.set(c, (count.get(c) ?? 0) + 1);
  let pairs = 0;
  for (const v of count.values()) pairs += Math.floor(v / 2);
  const n = words.length;
  let best = 0;
  for (let mask = 0; mask < 1 << n; mask++) {
    let need = 0, size = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) { need += Math.floor(words[i].length / 2); size++; }
    if (need <= pairs) best = Math.max(best, size);
  }
  return best;
}

