function mostMirrorWords(words: string[]): number {
  const count = new Array(26).fill(0);
  for (const w of words) for (let i = 0; i < w.length; i++) count[w.charCodeAt(i) - 97]++;
  let pairs = 0;
  for (const v of count) pairs += Math.floor(v / 2);
  const lens = words.map(w => w.length).sort((a, b) => a - b);
  let made = 0;
  for (const L of lens) {
    const cost = Math.floor(L / 2);
    if (cost > pairs) break;
    pairs -= cost;
    made++;
  }
  return made;
}

